//! Swiss income-tax deduction rules, imported from the ESTV tax
//! calculator's deduction exports.
//!
//! GENERATED by `tools/import_estv_deductions.py` -- do not edit by
//! hand; re-run the importer instead.
//!
//! Source: `estv_deductions.xlsx` (rules) and
//! `estv_deduction_scales.xlsx` (phase-out scales), both ESTV
//! publications for tax year 2025.
//!
//! # Two tables, two jobs
//!
//! [`DEDUCTION_RULES`] gives, per canton and per deduction, the amount
//! and the bounds the ESTV calculator applies:
//!
//! ```text
//! deduction = clamp(amount + percent/100 * base, minimum, maximum)
//! ```
//!
//! Note that `amount` and `percent` are **not** alternatives: Aargau's
//! "Pauschalabzug übrige Berufskosten" is `Betrag=700, Prozent=10,
//! Maximum=2400`, i.e. 700 plus 10% capped at 2400.
//!
//! [`DEDUCTION_SCALES`] gives the means-tested deductions as step
//! functions of net income. The amount is the one at the highest
//! threshold not exceeding income; these phase *down* as income rises.
//!
//! # These tables also contain non-deductions
//!
//! The rules file mixes in thresholds (`Schwellwert ...`), tax
//! reliefs (`Steuerermässigung pro Kind`) and rate constants
//! (`Maximaler technischer Zinssatz ...`). Summing every row would
//! double-count and would treat parameters as deductions, so each row
//! carries a [`RuleKind`] recording what it is. A consumer must
//! filter on `Deduction`.

/// What a row in the rules file actually is.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RuleKind {
    /// Reduces taxable income; may be summed with its siblings.
    Deduction,
    /// A threshold or phase-out breakpoint consumed by another rule.
    Threshold,
    /// A tax relief or a rate constant: not a deductible amount.
    Other,
}

/// One imported deduction rule for one canton (or `Bund`).
#[derive(Debug, Clone, Copy)]
pub struct DeductionRule {
    /// Canton code, or `Bund` for the federal rule.
    pub canton_code: &'static str,
    /// The ESTV `Abzug` label, verbatim. Kept as the source spells it so a
    /// rule can be found in the workbook by eye.
    pub name: &'static str,
    pub kind: RuleKind,
    /// Fixed amount in CHF.
    pub amount: f64,
    /// Percentage of the base, as a percentage (10.0 means 10%).
    pub percent: f64,
    /// Lower bound in CHF.
    pub minimum: f64,
    /// Upper bound in CHF; `0.0` means the source states no ceiling.
    pub maximum: f64,
}

/// One step of a means-tested deduction's phase-out table.
#[derive(Debug, Clone, Copy)]
pub struct ScalePoint {
    /// Net income (`Reineinkommen`) at which this step begins.
    pub threshold: f64,
    /// The deduction amount from this threshold onwards.
    pub amount: f64,
}

/// A means-tested deduction, expressed as a step function of net income.
#[derive(Debug, Clone, Copy)]
pub struct DeductionScale {
    pub canton_code: &'static str,
    pub name: &'static str,
    /// `Steuerhoheit` from the source: which level of government levies it.
    pub authority: &'static str,
    pub points: &'static [ScalePoint],
}

impl DeductionScale {
    /// The deduction at a given net income.
    ///
    /// Zero below the first threshold, then the amount at the highest
    /// threshold not exceeding the income. The tables phase down to zero,
    /// so this is a step function rather than an interpolation.
    pub fn amount_at(&self, net_income: f64) -> f64 {
        let mut amount = 0.0;
        for point in self.points {
            if net_income < point.threshold {
                break;
            }
            amount = point.amount;
        }
        amount
    }
}

impl DeductionRule {
    /// The deduction this rule yields on a given base (normally net
    /// income), before the means-tested scales are applied.
    ///
    /// `clamp(amount + percent/100 * base, minimum, maximum)`. A `maximum`
    /// of `0.0` means the source states no ceiling, which is *not* a
    /// ceiling of zero, so it is ignored.
    pub fn apply(&self, base: f64) -> f64 {
        let raw = self.amount + self.percent / 100.0 * base;
        let mut value = raw.max(self.minimum);
        if self.maximum > 0.0 {
            value = value.min(self.maximum);
        }
        value.max(0.0)
    }
}

